    context.innerHTML='<strong>Choose Option</strong><button data-act="follow">Follow <span>'+E(safeName(best))+'</span></button><button data-act="account">Account <span>'+E(safeName(best))+'</span></button><button data-act="xp">XP Tracker <span>'+E(safeName(best))+'</span></button>'+(b.reserved?'':'<button data-act="'+(held?'account-release':'account-pause')+'">'+(held?'Resume':'Pause')+' <span>'+E(safeName(best))+'</span></button>')+'<button data-act="examine">Examine <span>'+E(safeName(best))+'</span></button><button data-act="cancel">Cancel</button>';
