      const send=verb==='request'?(rest?{action:'request',extra:{text:rest.slice(0,500)}}:null):(rest&&/^[A-Za-z0-9]{1,12}$/.test(rest)?{action:verb==='pause'?'account-pause':'account-release',extra:{account:rest}}:null);
